cards.append(compact('fu_lian','浮莲','浮莲与朱槿、水荭同受特工训练，却更积极地靠近掌权者，希望取得远超工具身份的地位。在《算帐》的政治风暴中，一名官员死亡，她离开组织，带着巨款与秘密档案的传闻进入瑞士，成为多方追索的目标。朱槿认为她与死者合谋敛财，也怀疑她可能先下手杀人；这些判断没有在后文获得直接证实。浮莲自己留下的信则否认拥有那份足以毁掉所有人的资料，也否认外界描述的全部男女关系。她能在路旁小食店扮作女侍，把地下电脑室隐藏在层层机关之后，在白素到来前及时转移；这表明她确有行动和隐蔽本领，而非只是受保护的情妇。信中她直陈被找到就可能死亡，试图让白素理解双方承受的代价并不对等。她是否亲自打电话引白素找到信，是卫白的推断，不能当作亲见事实。其藏身地留下威力很大的毁灭装置，后来由白素启动，连地下室一起消失；炸药由谁发明、她还持有多少，均未知。此后浮莲没有再传来消息，卡片保留她求生、争地位和利用信息差的性格，也保留她的证言可能自保而未获验证的部分。','逃离瑞士藏身处后去向不明，未证实死亡或被组织捕回；原据点及其中装置已毁',['主角','阶段性对立者'],'脱离追捕，保存自己决定生活的机会，不愿成为他人营救计划的代价','布置隐蔽身份和退路，必要时通过文字说明自身处境','认为暴露会致命时先离开再留下选择性信息，不为了昔日同门自动交出底牌','外人对她的指控与她自己的辩白都要查验，逃亡成功不能证明全部传闻为真',[ab('特工隐蔽与后路经营','借女侍身份、暗室电脑和预备路线躲避追查','仍需实际据点与资讯；没有证据证明能永远躲过任何追踪'),ab('据点毁灭装置','原藏身店铺内有能毁灭建筑和地下室的预置炸药','该装置已由白素引爆；种类、发明者及备用存量未知，不计常驻个人火力',kind='历史设施')],[ev('114',1986,2028,'同门背景、他人眼中的野心与谋杀猜测'),ev('114',2428,2444,'留下信件否认资料与完整关系传闻'),ev('114',2466,2512,'暗室电脑设施与引路电话推断'),ev('114',2653,2666,'据点毁灭及此后失去消息')],profile='investigator',extra={'uncertainties':['杀死官员与贪污细节主要来自他人判断，未被亲见证实。','浮莲是否发明据点炸药是卫的推测。','她是否根本没有档案，只有本人信件证言，未取得可独立验证的原件。']}))
cards.append(compact('suan_hermaphrodite','算帐中的双性特工','这位未具姓名的特工在瑞士小食店与一名动作极快的女子联袂出现，代表追索浮莲档案的势力向卫氏夫妇索取资料。卫斯理最初以为眼前的中年男子只是女子化装，对方则自述是双性人，穿男装女装都不算在性别上扮演；这里的身份说明不是战力来源，真正可核的是稳健、强悍而懂得交涉的行动。他直截了当地要求开价，同伴夺取样品遭卫白围堵时，他及时撞开卫斯理，继而踩住对方背部，却又被白素的冰插抵住颈侧。四人的相互牵制证明他足以进入顶尖近身高手的角力，也证明他并不免疫器械伤害。局面僵持后，他没有逞气硬拚，重提先看样品再议条件的约定，道歉退开，使双方能够继续谈判。后来他带着已经获释的铁天音和各派代表登门，把放人包装为见面礼，以降低卫斯理可能提出的交换条件。实际上，他拿到的是利用各派心虚所伪造的资料，并未识破这个骗局。终局他为争夺秘密而来，又因务实谈判使铁家父子重聚；既非温和好人，也不是只会用蛮力的打手。','取得卫白伪造的软件并代表各派达成交易；铁天音已经释放，他未识破资料真伪','阶段性对立者','为雇主取得危险资料，同时用可承受的条件避免失控冲突','言语简短直接，先问价码和条件，不绕远路制造神秘感','同伴被制时立即以近身力量相救，互相牵制后能迅速退让','把任务结果看得比争一时面子更重，但可能高估情报的真实性',[ab('强力近战与搭档协作','侧撞卫斯理并以身体位置制住其背，给同伴争取脱身','仍被白素冰插威胁颈动脉；力量高不意味着抗锐器'),ab('交换与代表谈判','先索取样品，后带人质获释作为见面礼并协调各派','依雇主授权和其对资料的判断；不能独立指挥所有政治势力')],[ev('114',2571,2590,'化装与自述双性身份、提出条件交换'),ev('114',2591,2639,'撞击、相互制约、道歉退开'),ev('114',2678,2683,'铁蛋不识其来历'),ev('114',2745,2778,'带铁天音和各派代表登门达成交易')],profile='strong',aliases=['雌半雄（算帐原文称谓）'],extra={'appearance':{'description':'出场经过化装，呈中年男子外观；真实五官与姓名未明。','portrayal':'压低声音直入主题，在危险僵局中也能镇定谈条件。'},'uncertainties':['是否属于十二花训练体系未确定，铁蛋说从未认识这两名特工。','双性身份依本人自述，不推导任何额外生理力量或性格特征。']}))
cards.append(compact('suan_fast_agent','算帐中的迅捷女特工','这位未具姓名的女子与双性特工共同到瑞士追索浮莲的秘密档案，外表经化装显得普通，目光却十分警觉。她一进店便认出白素的伪装，用带讥刺的口吻点明对方身份，不把看似平常的小食店当作寻常环境。得到取样的口头约定后，她只凭卫白望向碟子的视线，立即判断软件所在，闪身取到手中。卫斯理认为她反应、判断和速度都是罕见水准，但这只是对近身本领的评价，不意味着任意超音速。白素突然射出滚水迫她后退，她因撞翻物件短暂受阻，卫斯理抓住半步先机，最终以地趟擒拿锁住脚踝、压住咽喉。她吃亏的重要原因，是一只手始终不愿放开任务物件。搭档出手相救，形成互相牵制后，她接受议价，带样品迅速离去；后来又随同登门，让铁天音获释成为谈判的开场。她没有独立的超常技术，也未识破样品是假。卡片将她写成敢抢先、重结果的行动者，遇到目标与自身安全冲突时可能抓得太紧，这种小小的执着会比固定的炫技姿势更影响现场选择。','携样品离店后参与释放铁天音的谈判队伍；拿到的是伪造资料，真实来历与后续任务不明','阶段性对立者','取得任务指定的情报，并在高手对峙中维护自己的行动主动权','先观察视线、位置和出口，往往在别人说完之前完成取物','目标已在手时倾向紧握不放，即使因此牺牲回避空间；受制后会接受可完成任务的交换','速度优势需要空间和判断，不能把一次抢先等同永远无人能拦',[ab('迅捷取物与近战反应','凭目光判断软件位置，快速取物及退避突袭','会被环境障碍拖慢，被踝部擒拿和咽喉压制；需要肉身可移动空间')],[ev('114',2571,2576,'识破化装与质问'),ev('114',2591,2617,'抢样、躲滚水、因撞物和不放软件被制'),ev('114',2625,2638,'对取样的理由与迅速离开'),ev('114',2767,2778,'参与终局谈判')],profile='martial',extra={'appearance':{'description':'经精心化装，面貌普通，双眼闪亮敏锐；真容未描写。','portrayal':'动作先于长篇解释，受挫时面色变化明显，仍能迅速恢复行动。'}}))
cards.append(compact('suan_driver','瑞士的胖司机','这名没有留下姓名的胖司机原是白老大的旧相识，后来在瑞士替白素接应卫斯理。他驾着出租车沉默等候，接到人后不急着去目的地，而是在市区迂回两圈，巧妙甩掉可疑车辆，再把乘客送到郊外小食店。卫斯理称赞他的手段，他只是从倒后镜笑一笑，没有多作解释。这种职业化的冷静最初使人放心，却并不等同于可靠的道德承诺。寻找浮莲档案的赏格高达一亿瑞士法郎，白素早已承认旧交未必经得住诱惑，仍利用他作为让消息传开的途径。果然，后来来店取资料的两名高手，正坐着他的车抵达，原文据此说明他出卖了卫白。他的背叛反而符合二人的诱敌计划，不能据此说他是知情配合的盟友。司机既无超能力，也没有直接参与店里的四人搏斗；可用本领是驾驶、辨别尾随、运输和把关系变成交易的经验。他在新场景中的选择会取决于眼前利益、承诺和被揭穿的风险，而不该因为旧日交情便自动忠诚，也不该把一次成功甩尾变成永不失手的逃脱保证。','把两名追索者送至小食店后不再有独立后续；出卖接送信息已被卫白预料并利用','阶段性对立者','利用驾驶与熟人关系获得报酬，在高额诱惑下把乘客信息变成筹码','少说话，先观察后视镜和道路，再以熟练路线安排运输','高额赏格与秘密同时出现时可能选择转卖消息，不会因旧交自动守密','擅长实际道路上的判断，却不一定看穿乘客为何主动容忍出卖',[ab('驾驶与反跟踪','在城市道路迂回，识别并甩开可疑车辆后送达隐蔽地点','需要车辆、道路和可观察的跟踪者，不保证摆脱高科技监控')],[ev('114',2404,2414,'驾驶、绕行与甩尾能力'),ev('114',2505,2512,'旧交与赏金诱惑下的可靠性边界'),ev('114',2561,2567,'再次运送追索者，出卖被利用')],profile='ordinary'))
cards.append(compact('suan_dead_official','算帐中的已死官员','《算帐》中这名未具姓名的中级官员已经死亡，公开结论称为自杀，却因财富、亲密关系和派系背景留下巨大风波。铁天音曾是他的得力助手，而且这个职位由其后台安排；他的死亡因此不只结束一个人的生命，也把助手推到争夺秘密、扩大打击和防止泄密的交叉处。旁人说他拥有巨额财富和众多情妇，朱槿又把浮莲描述为替他保管赃款与机密的人，认为两人曾准备足以牵制各派的退路。这些说法塑造了一个借权力获利、以隐秘关系自保的官员形象，但浮莲留信否认了档案的存在以及外界所说的全部关系，故事没有给读者可独立核验的原始账目。卫斯理怀疑他被自己人灭口，朱槿也提出浮莲杀人的可能，两种都没有得到证实。因此卡片保留贪腐嫌疑和权力网络带来的危害，同时不把推理写成他的亲口供认。作为角色，他最有戏剧性的局限是误以为财富与秘密足以提供退路，却没能逃过权位变化；死后别人仍争夺他的名字和资料传闻，而他已无法决定自己的解释。','开篇前已死亡，公开称自杀，实际死因及是否有真实秘密档案未查明','反派','按他人证言，追求财富、地位及对权力风险的自保；内心未获直接描写','通过职位、人事和隐秘利益关系行动，具体操作只采用原文已知部分','势力变化时可能寻找资料和关系作为保障，但故事已经表明这不足以保证生还','不得以叙述者的推测补全一套确定的阴谋或自杀动机',[ab('职务与人事资源','曾拥有官员职位、后台支持及铁天音等助手','属于依附政治环境的社会资源，不是个人火力；终局已亡、原关系不能自动恢复')],[ev('114',1121,1128,'助手任命、公开自杀说与灭口推断'),ev('114',1888,1894,'财富及关系传闻'),ev('114',1986,2021,'浮莲和档案说法及不同死因猜测'),ev('114',2431,2439,'浮莲否认档案与外界关系说法')],profile='expert'))
